WITH flattened AS (SELECT id, plan, currency, element FROM price_tiers LATERAL VIEW EXPLODE(tier_prices) x AS element) SELECT CASE WHEN element >= 61 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, COUNT_IF(plan = 'basic') AS basic_events, AVG(element) FILTER (WHERE plan = 'basic') AS basic_avg_element, COUNT(*) AS event_count FROM flattened GROUP BY element_tier ORDER BY basic_avg_element ASC NULLS LAST
